"""Equivalence check: compiled native GEOMETRY node vs the original mPyNode.
Run in Maya. Rebuilds the Python original from the embedded spec, builds
the compiled node, drives identical inputs, and compares the built
geometry (topology + every point) via the authoritative geo parity
branch in verify._verify_one.
"""
import os, json
import maya.cmds as cmds

BUNDLE = os.path.join(os.path.dirname(__file__), 'helixCurve.mll')
SPEC   = json.loads('{"schema_version": 1, "source_node": "helixCurve", "mpy_type": "mPyNurbsCurve", "suggested": {"node_type_name": "helixCurve", "class_name": "HelixCurve", "type_id": "0x00071d1d", "mpx_base": "MPxNode", "note": "outputs a nurbsCurve data attr", "heaviness": "medium"}, "inputs": {"radius": {"type": "float", "is_array": false, "portable": true, "cpp": {"cat": "scalar", "fn": "MFnNumericAttribute", "data": "kFloat", "cpp": "float", "read": "asFloat", "portable": true}, "default_value": 2.0}, "height": {"type": "float", "is_array": false, "portable": true, "cpp": {"cat": "scalar", "fn": "MFnNumericAttribute", "data": "kFloat", "cpp": "float", "read": "asFloat", "portable": true}, "default_value": 6.0}, "turns": {"type": "float", "is_array": false, "portable": true, "cpp": {"cat": "scalar", "fn": "MFnNumericAttribute", "data": "kFloat", "cpp": "float", "read": "asFloat", "portable": true}, "default_value": 3.0}, "t": {"type": "time", "is_array": false, "portable": true, "cpp": {"cat": "unit", "fn": "MFnUnitAttribute", "data": "kTime", "cpp": "double", "read": "asMTime", "portable": true}}}, "outputs": {}, "variables": {}, "compute": "# Procedural HELIX generator. Builds the (N, 3) CV positions and hands them to\\n# the NurbsCurve constructor: a coil of `radius`, total rise `height`, `turns`\\n# full revolutions. `t` (a time input auto-wired to the timeline) slowly spins\\n# the coil so it animates on playback. NurbsCurve marshals the CVs ->\\n# kNurbsCurveData; the native compile reproduces that build step, so this lowers\\n# to pure C++.\\nimport numpy as np\\nn = 120\\nu = np.linspace(0.0, 1.0, n)\\nang = u * self.turns * 2.0 * np.pi + self.t * 0.05\\nx = self.radius * np.cos(ang)\\nz = self.radius * np.sin(ang)\\ny = (u - 0.5) * self.height\\ncvs = np.stack([x, y, z], axis=1)\\nself.outCurve = NurbsCurve(points=cvs, degree=3)\\n", "init": "import numpy as np\\nfrom mpynode._api2.geometry import NurbsCurve\\n", "affects": "all", "external_helpers": "# --- from module \'mpynode._api2.geometry\' ---\\nclass NurbsCurve:\\n    \\"\\"\\"A NURBS curve geometry object -- the SAME type on inputs and outputs.\\n\\n    Two modes (mirrors :class:`Mesh`):\\n\\n    * **Attached** (what an input plug hands you): holds the retained geometry\\n      DATA MObject and lazily mints an ``MFnNurbsCurve`` from it. The numpy read\\n      surface (``points``/``cvs`` / ``degree`` / ``form`` / ``knots`` /\\n      ``component_tags``) is materialized on first access and cached. EM-safe.\\n    * **Value** (what you construct or ``copy()``): a plain arrays bucket you\\n      assign to an output plug. ``build_curve_data`` marshals it (duck-typed).\\n\\n    Self-sufficient: the raw function set is ``fn`` (any ``MFnNurbsCurve`` method\\n    also works via delegation, e.g. ``curve.cvPositions(...)`` keeps working).\\n    ``copy()`` returns a detached editable value you can send to an output with\\n    NO imports.\\n\\n    Construction (value/output): ``points`` (N,3 CV positions) required.\\n    Optional: ``degree`` (default 3), ``periodic`` (default False = open),\\n    ``kv`` (knot vector; auto if None). ``knots`` is an alias for ``kv``.\\n    \\"\\"\\"\\n\\n    def __init__(self, points=None, degree=3, periodic=False, kv=None):\\n        self._attached = False\\n        self._data = None          # retained api2 geometry DATA MObject\\n        self._fn = None            # cached MFnNurbsCurve (attached mode)\\n        self._tags = None          # cached component_tags dict\\n        self._points = None if points is None else np.asarray(points, dtype=np.float64)\\n        self._degree = int(degree) if degree is not None else 3\\n        self._periodic = bool(periodic)\\n        self._knots = None if kv is None else np.asarray(kv, dtype=np.float64)\\n        self._form = None          # value mode derives form from periodic\\n\\n    @classmethod\\n    def _attach(cls, data_mobject, source_plug=None):\\n        c = cls.__new__(cls)\\n        c._attached = True\\n        c._data = data_mobject\\n        c._fn = None\\n        c._tags = None\\n        c._points = None\\n        c._degree = None\\n        c._periodic = None\\n        c._knots = None\\n        c._form = None\\n        c._src_plug = source_plug\\n        c._name = None\\n        return c\\n\\n    @property\\n    def name(self):\\n        \\"\\"\\"Name of the shape feeding this curve, or None for a value curve.\\n        Lazy + cached -- see :func:`_source_node_name`.\\"\\"\\"\\n        nm = self.__dict__.get(\\"_name\\")\\n        if nm is None:\\n            nm = _source_node_name(self.__dict__.get(\\"_src_plug\\"))\\n            self.__dict__[\\"_name\\"] = nm\\n        return nm\\n\\n    # ----- raw function set + delegation -----\\n    @property\\n    def fn(self):\\n        \\"\\"\\"The live ``MFnNurbsCurve`` (attached mode), or None if detached.\\"\\"\\"\\n        f = self.__dict__.get(\\"_fn\\")\\n        if f is None:\\n            d = self.__dict__.get(\\"_data\\")\\n            if d is not None and not d.isNull():\\n                f = om.MFnNurbsCurve(d)\\n                self.__dict__[\\"_fn\\"] = f\\n        return f\\n\\n    def __getattr__(self, name):\\n        if name.startswith(\\"_\\"):\\n            raise AttributeError(name)\\n        f = self.fn\\n        if f is not None:\\n            return getattr(f, name)\\n        raise AttributeError(\\n            \\"%r: this NurbsCurve is detached (arrays only, no function set)\\" % name)\\n\\n    def _cow_detach(self):\\n        if not self.__dict__.get(\\"_attached\\"):\\n            return\\n        _ = self.points; _ = self.degree; _ = self.form; _ = self.knots\\n        try:\\n            _ = self.component_tags\\n        except Exception:\\n            pass\\n        self._attached = False\\n        self._data = None\\n        self._fn = None\\n\\n    # ----- lazy numpy read surface -----\\n    @property\\n    def points(self):\\n        v = self.__dict__.get(\\"_points\\")\\n        if v is None and self.__dict__.get(\\"_attached\\"):\\n            f = self.fn\\n            if f is not None:\\n                v = np.asarray(\\n                    f.cvPositions(om.MSpace.kObject))[:, :3].astype(np.float64)\\n                self._points = v\\n        return v\\n\\n    @points.setter\\n    def points(self, val):\\n        self._cow_detach()\\n        self._points = None if val is None else np.asarray(val, dtype=np.float64)\\n\\n    # ``cvs`` reads the same CV positions (matches the generator scratch name).\\n    @property\\n    def cvs(self):\\n        return self.points\\n\\n    @cvs.setter\\n    def cvs(self, val):\\n        self.points = val\\n\\n    @property\\n    def degree(self):\\n        v = self.__dict__.get(\\"_degree\\")\\n        if v is None and self.__dict__.get(\\"_attached\\"):\\n            f = self.fn\\n            if f is not None:\\n                v = int(f.degree)\\n                self._degree = v\\n        return v\\n\\n    @degree.setter\\n    def degree(self, val):\\n        self._cow_detach()\\n        self._degree = None if val is None else int(val)\\n\\n    @property\\n    def form(self):\\n        v = self.__dict__.get(\\"_form\\")\\n        if v is None and self.__dict__.get(\\"_attached\\"):\\n            f = self.fn\\n            if f is not None:\\n                v = int(f.form)\\n                self._form = v\\n        return v\\n\\n    @form.setter\\n    def form(self, val):\\n        self._cow_detach()\\n        self._form = val\\n\\n    @property\\n    def periodic(self):\\n        # Value mode stores an explicit bool; attached mode derives it from form.\\n        p = self.__dict__.get(\\"_periodic\\")\\n        if p is not None:\\n            return p\\n        fm = self.form\\n        return bool(fm == om.MFnNurbsCurve.kPeriodic) if fm is not None else False\\n\\n    @periodic.setter\\n    def periodic(self, val):\\n        self._cow_detach()\\n        self._periodic = bool(val)\\n\\n    @property\\n    def knots(self):\\n        v = self.__dict__.get(\\"_knots\\")\\n        if v is None and self.__dict__.get(\\"_attached\\"):\\n            f = self.fn\\n            if f is not None:\\n                v = np.asarray(f.knots(), dtype=np.float64)\\n                self._knots = v\\n        return v\\n\\n    @knots.setter\\n    def knots(self, val):\\n        self._cow_detach()\\n        self._knots = None if val is None else np.asarray(val, dtype=np.float64)\\n\\n    # ``kv`` is the name ``build_curve_data`` reads; alias it to ``knots`` so a\\n    # copy()\'d attached curve round-trips its real knot vector on output.\\n    @property\\n    def kv(self):\\n        return self.knots\\n\\n    @kv.setter\\n    def kv(self, val):\\n        self.knots = val\\n\\n    @property\\n    def component_tags(self):\\n        \\"\\"\\"``{tag_name: {\\"type\\": \\"cv\\", \\"indices\\": np}}`` (curve CV tags are\\n        single-indexed). Read live off the geometry DATA (attached mode).\\"\\"\\"\\n        t = self.__dict__.get(\\"_tags\\")\\n        if t is None:\\n            t = {}\\n            d = self.__dict__.get(\\"_data\\")\\n            if self.__dict__.get(\\"_attached\\") and d is not None and not d.isNull():\\n                try:\\n                    gd = om.MFnGeometryData(d)\\n                    for nm in gd.componentTags():\\n                        try:\\n                            comp = gd.componentTagContents(nm)\\n                            typ, idx = _decode_single_component(comp)\\n                            t[nm] = {\\"type\\": typ, \\"indices\\": idx}\\n                        except Exception:\\n                            pass\\n                except Exception:\\n                    pass\\n            self._tags = t\\n        return t\\n\\n    def region(self, tag):\\n        \\"\\"\\"CV positions of a ``cv`` tag (``(K,3)``), or its raw indices for any\\n        other tag type, or None if the tag is absent.\\"\\"\\"\\n        info = self.component_tags.get(tag)\\n        if not info:\\n            return None\\n        idx = info[\\"indices\\"]\\n        if info[\\"type\\"] == \\"cv\\":\\n            pts = self.points\\n            return pts[idx] if pts is not None else None\\n        return idx\\n\\n    def copy(self):\\n        \\"\\"\\"A DETACHED value copy (severs the .fn link). Edit its channels and\\n        assign to an output plug -- no imports required.\\"\\"\\"\\n        c = NurbsCurve()\\n        p = self.points\\n        c._points = None if p is None else np.array(p, dtype=np.float64)\\n        c._degree = self.degree\\n        c._form = self.form\\n        c._periodic = self.periodic\\n        k = self.knots\\n        c._knots = None if k is None else np.array(k, dtype=np.float64)\\n        try:\\n            c._tags = {kk: dict(vv) for kk, vv in self.component_tags.items()}\\n        except Exception:\\n            pass\\n        return c\\n\\n    # ----- serialization -----\\n    def __reduce__(self):\\n        \\"\\"\\"Pickle as a DETACHED value curve (see the Serialization section).\\"\\"\\"\\n        return (_geo_from_state, (NurbsCurve, _detached_state(self)))\\n\\n    def to_json(self):\\n        \\"\\"\\"A plain-JSON dict of every channel -- no numpy, no Maya handles.\\"\\"\\"\\n        return {\\n            \\"type\\": \\"NurbsCurve\\",\\n            \\"name\\": self.name,\\n            \\"points\\": _jlist(self.points),\\n            \\"degree\\": None if self.degree is None else int(self.degree),\\n            \\"form\\": self.form,\\n            \\"periodic\\": bool(self.periodic),\\n            \\"knots\\": _jlist(self.knots),\\n            \\"component_tags\\": _jtags(self.component_tags),\\n        }\\n\\n    @classmethod\\n    def from_json(cls, payload):\\n        \\"\\"\\"Rebuild a detached NurbsCurve from :meth:`to_json` output.\\"\\"\\"\\n        if isinstance(payload, (str, bytes)):\\n            payload = _json.loads(payload)\\n        c = cls(points=payload.get(\\"points\\"),\\n                degree=payload.get(\\"degree\\") or 3,\\n                periodic=bool(payload.get(\\"periodic\\")),\\n                kv=payload.get(\\"knots\\"))\\n        c._form = payload.get(\\"form\\")\\n        c._tags = _tags_from_json(payload.get(\\"component_tags\\"))\\n        c._name = payload.get(\\"name\\")\\n        return c\\n\\n    # ----- arithmetic -----\\n    __array_ufunc__ = None\\n\\n    def __iadd__(self, other):\\n        \\"\\"\\"Concatenate another curve\'s CVs onto this one, producing ONE longer\\n        curve through both control point sets -- not two curves in one shape.\\n\\n        Knots are dropped so the marshaller rebuilds a uniform vector for the\\n        combined CV count: the originals describe the old parameterisations and\\n        cannot be spliced. Degree and ``periodic`` must MATCH -- silently\\n        re-fitting to another degree, or appending onto a closed curve, is far\\n        more likely a mistake than an intent.\\"\\"\\"\\n        if not isinstance(other, NurbsCurve):\\n            raise TypeError(\\n                \\"NurbsCurve + %s is undefined; only another NurbsCurve can be \\"\\n                \\"concatenated\\" % type(other).__name__)\\n        if int(other.degree) != int(self.degree):\\n            raise ValueError(\\n                \\"degree mismatch: %d vs %d -- resample one curve first\\"\\n                % (int(self.degree), int(other.degree)))\\n        if bool(other.periodic) != bool(self.periodic):\\n            raise ValueError(\\n                \\"periodic mismatch: %r vs %r -- appending onto a closed curve \\"\\n                \\"is ambiguous\\" % (bool(self.periodic), bool(other.periodic)))\\n        op = other.points\\n        self._cow_detach()\\n        sp = self.__dict__.get(\\"_points\\")\\n        if op is None:\\n            return self\\n        if sp is None:\\n            self._points = np.array(op, dtype=np.float64)\\n        else:\\n            self._points = np.concatenate(\\n                [sp, np.asarray(op, dtype=np.float64)])\\n        self._knots = None\\n        return self\\n\\n    def __add__(self, other):\\n        return self.copy().__iadd__(other)\\n\\n    def __radd__(self, other):\\n        if isinstance(other, int) and other == 0:\\n            return self.copy()\\n        return self.__add__(other)\\n\\n    def to_mobject(self):\\n        # Attached + unedited: zero-copy, tag-preserving pass-through.\\n        if self.__dict__.get(\\"_attached\\"):\\n            d = self.__dict__.get(\\"_data\\")\\n            if d is not None and not d.isNull():\\n                return d\\n        return build_curve_data(self)\\n\\n    def __repr__(self):\\n        nm = self.name\\n        if nm:\\n            return \'NurbsCurve(\\"%s\\")\' % nm\\n        mode = \\"attached\\" if self.__dict__.get(\\"_attached\\") else \\"value\\"\\n        p = self.__dict__.get(\\"_points\\")\\n        n = (\\"lazy\\" if self.__dict__.get(\\"_attached\\") else 0) if p is None else len(p)\\n        return \\"<NurbsCurve %s cvs=%s>\\" % (mode, n)\\n\\ndef _decode_single_component(comp):\\n    \\"\\"\\"Decode a single-indexed component MObject into ``(type_str, indices)``.\\n    ``indices`` is a flat ``(K,)`` int64 array.\\"\\"\\"\\n    if comp is None or comp.isNull():\\n        return \\"unknown\\", np.empty(0, dtype=np.int64)\\n    typ = _COMP_TYPE.get(comp.apiType(), \\"unknown\\")\\n    try:\\n        sic = om.MFnSingleIndexedComponent(comp)\\n        idx = np.asarray(sic.getElements(), dtype=np.int64)\\n    except Exception:\\n        idx = np.empty(0, dtype=np.int64)\\n    return typ, idx\\n\\ndef _detached_state(obj):\\n    \\"\\"\\"The picklable ``__dict__`` of ``obj`` -- its channels, materialized off\\n    the live handle if attached, with the Maya handles dropped.\\"\\"\\"\\n    state = obj.copy().__dict__.copy()\\n    state.pop(\\"_data\\", None)\\n    state.pop(\\"_fn\\", None)\\n    state[\\"_attached\\"] = False\\n    state[\\"_name\\"] = obj.name          # keep the source-shape label for display\\n    return state\\n\\ndef _geo_from_state(cls, state):\\n    \\"\\"\\"Unpickle hook: rebuild a DETACHED geometry object from its channels.\\n\\n    Module-level (pickle must import it by name) and shared by all three\\n    geometry types -- the state dict is just the detached ``__dict__``.\\"\\"\\"\\n    obj = cls.__new__(cls)\\n    obj.__dict__.update(state)\\n    return obj\\n\\ndef _jlist(arr):\\n    \\"\\"\\"A numpy array as nested JSON lists (or None).\\"\\"\\"\\n    return None if arr is None else np.asarray(arr).tolist()\\n\\ndef _jtags(tags):\\n    return {k: {\\"type\\": v.get(\\"type\\"), \\"indices\\": _jlist(v.get(\\"indices\\"))}\\n            for k, v in (tags or {}).items()}\\n\\ndef _source_node_name(plug):\\n    \\"\\"\\"Name of the node FEEDING ``plug``, or None.\\n\\n    DISPLAY ONLY -- this is what lets a geometry object print as\\n    ``Mesh(\\"pCubeShape1\\")`` instead of an anonymous blob. An attached object\\n    holds datablock DATA, which carries no identity of its own, so the identity\\n    has to come from the plug it was decoded off.\\n\\n    Resolved LAZILY and cached by the caller: it must never cost anything on the\\n    compute hot path, only when something actually displays the object. An\\n    unconnected plug has no meaningful source -- return None and let the caller\\n    fall back to a structural summary rather than naming the consuming node\\n    (``mPyMesh1`` is not the name of the mesh).\\n\\n    Not every geometry read can supply a plug: ``_read_handle_value`` is\\n    contracted plug-free for the worker-thread compute path (Hypershade swatch /\\n    Arnold), where plug access is unsafe. Objects decoded there carry\\n    ``source_plug=None`` and simply repr with their structural summary -- a\\n    display label is never worth weakening that contract.\\n    \\"\\"\\"\\n    if plug is None:\\n        return None\\n    try:\\n        src = plug.source()\\n        if src.isNull:\\n            return None\\n        return om.MFnDependencyNode(src.node()).name()\\n    except Exception:\\n        return None\\n\\ndef _tags_from_json(payload):\\n    return {k: {\\"type\\": v.get(\\"type\\"),\\n                \\"indices\\": np.asarray(v.get(\\"indices\\") or [], dtype=np.int64)}\\n            for k, v in (payload or {}).items()}\\n\\ndef build_curve_data(obj):\\n    \\"\\"\\"Marshal a curve-like object into an ``MFnNurbsCurveData`` MObject.\\n\\n    Required attr: ``points`` (CV positions, ``(N, 3)``). Optional: ``degree``\\n    (default 3), ``periodic`` (default False), ``kv`` (knot vector; auto if\\n    None or wrong length). An optional legacy ``form`` attribute\\n    (``\\"open\\"``/``\\"closed\\"``/``\\"periodic\\"``) overrides ``periodic`` -- the\\n    ``build_default_output`` shim uses it to keep the ``closed`` form\\n    reachable. Returns an empty data MObject on failure.\\n    \\"\\"\\"\\n    data_obj = om.MFnNurbsCurveData().create()\\n\\n    cvs = _as_points(getattr(obj, \\"points\\", None), _CURVE_TAG)\\n    if cvs is None or cvs.shape[0] == 0:\\n        return data_obj\\n\\n    degree = getattr(obj, \\"degree\\", 3)\\n    degree = int(degree) if degree is not None else 3\\n    if degree not in _VALID_DEGREES:\\n        _log(f\\"[{_CURVE_TAG}] invalid degree {degree}; defaulting to 3\\")\\n        degree = 3\\n\\n    form_kind, periodic = _resolve_curve_form(obj)\\n    num_cvs = int(cvs.shape[0])\\n    if num_cvs < degree + 1:\\n        _log(f\\"[{_CURVE_TAG}] need at least degree+1 CVs ({degree + 1}); \\"\\n             f\\"got {num_cvs}; empty curve\\")\\n        return data_obj\\n\\n    kv = getattr(obj, \\"kv\\", None)\\n    if kv is None:\\n        knot_list = _curve_uniform_knots(num_cvs, degree, periodic)\\n    else:\\n        try:\\n            knot_list = [float(k) for k in\\n                         np.asarray(kv, dtype=np.float64).flatten()]\\n        except Exception:\\n            knot_list = _curve_uniform_knots(num_cvs, degree, periodic)\\n\\n    expected = _expected_knots(num_cvs, degree)\\n    if len(knot_list) != expected:\\n        if kv is not None:\\n            _log(f\\"[{_CURVE_TAG}] knot count {len(knot_list)} != expected \\"\\n                 f\\"{expected}; rebuilding uniform\\")\\n        knot_list = _curve_uniform_knots(num_cvs, degree, periodic)\\n\\n    try:\\n        pts_array = om.MPointArray([om.MPoint(float(p[0]), float(p[1]),\\n                                              float(p[2])) for p in cvs])\\n        knot_array = om.MDoubleArray([float(k) for k in knot_list])\\n        om.MFnNurbsCurve().create(pts_array, knot_array, degree, form_kind,\\n                                  False, False, data_obj)\\n    except Exception as exc:\\n        _log(f\\"[{_CURVE_TAG}] MFnNurbsCurve.create failed: {exc}\\")\\n        import traceback\\n        traceback.print_exc(file=sys.stderr)\\n        return om.MFnNurbsCurveData().create()\\n    return data_obj\\n\\ndef _as_points(arr, tag):\\n    \\"\\"\\"Coerce ``arr`` to an ``(N, 3)`` float64 array, or None.\\"\\"\\"\\n    if arr is None:\\n        return None\\n    try:\\n        out = np.asarray(arr, dtype=np.float64)\\n    except Exception:\\n        _log(f\\"[{tag}] points not float-coercible\\")\\n        return None\\n    if out.ndim != 2 or out.shape[1] != 3:\\n        _log(f\\"[{tag}] points must be (N, 3); got shape {out.shape}\\")\\n        return None\\n    return out\\n\\ndef _curve_uniform_knots(num_cvs, degree, periodic):\\n    \\"\\"\\"Uniform knot vector, length ``num_cvs + degree - 1`` for both forms.\\n    Open: clamped (multiplicity ``degree`` at the ends). Periodic: continuous\\n    integers ``[-degree+1 .. num_cvs-1]`` (matches Maya\'s periodic convention;\\n    the caller must supply CVs that already wrap).\\"\\"\\"\\n    n_knots = _expected_knots(num_cvs, degree)\\n    if n_knots <= 0:\\n        return []\\n    if periodic:\\n        return [float(i - degree + 1) for i in range(n_knots)]\\n    inner = max(n_knots - 2 * degree, 0)\\n    knots = [0.0] * degree\\n    knots.extend(float(i + 1) for i in range(inner))\\n    knots.extend([float(inner + 1)] * degree)\\n    return knots[:n_knots]\\n\\ndef _expected_knots(num_cvs, degree):\\n    \\"\\"\\"Knot count Maya\'s ``MFn*::create`` expects: ``num_cvs + degree - 1``\\n    for BOTH open and periodic forms (verified against a stock periodic\\n    circle: 11 CVs, degree 3 -> 13 knots = 11 + 3 - 1).\\"\\"\\"\\n    return num_cvs + degree - 1\\n\\ndef _log(msg: str) -> None:\\n    sys.stderr.write(msg if msg.endswith(\\"\\\\n\\") else msg + \\"\\\\n\\")\\n\\ndef _resolve_curve_form(obj):\\n    \\"\\"\\"Return ``(form_kind, periodic_bool)``.\\n\\n    Honors an optional legacy ``form`` attribute (a string\\n    ``\\"open\\"``/``\\"closed\\"``/``\\"periodic\\"`` or an int ``MFnNurbsCurve`` form\\n    constant) which the ``build_default_output`` shim passes through so the\\n    ``closed`` form the periodic-only :class:`NurbsCurve` can\'t express is not\\n    lost. If ``form`` is absent (the dataclass case) it falls back to the\\n    ``periodic`` bool. ``periodic_bool`` drives uniform knot generation\\n    (clamped vs continuous), so ``closed`` -> ``False`` -> clamped knots,\\n    matching the legacy marshaller.\\"\\"\\"\\n    form = getattr(obj, \\"form\\", None)\\n    if form is not None:\\n        if isinstance(form, str):\\n            kind = _CURVE_FORM_BY_NAME.get(form.lower(), om.MFnNurbsCurve.kOpen)\\n        elif isinstance(form, int) and not isinstance(form, bool):\\n            kind = int(form)\\n        else:\\n            kind = om.MFnNurbsCurve.kOpen\\n        return kind, (kind == om.MFnNurbsCurve.kPeriodic)\\n    periodic = bool(getattr(obj, \\"periodic\\", False))\\n    return (om.MFnNurbsCurve.kPeriodic if periodic\\n            else om.MFnNurbsCurve.kOpen), periodic", "external_helper_units": [{"module": "mpynode._api2.geometry", "name": "NurbsCurve", "source": "class NurbsCurve:\\n    \\"\\"\\"A NURBS curve geometry object -- the SAME type on inputs and outputs.\\n\\n    Two modes (mirrors :class:`Mesh`):\\n\\n    * **Attached** (what an input plug hands you): holds the retained geometry\\n      DATA MObject and lazily mints an ``MFnNurbsCurve`` from it. The numpy read\\n      surface (``points``/``cvs`` / ``degree`` / ``form`` / ``knots`` /\\n      ``component_tags``) is materialized on first access and cached. EM-safe.\\n    * **Value** (what you construct or ``copy()``): a plain arrays bucket you\\n      assign to an output plug. ``build_curve_data`` marshals it (duck-typed).\\n\\n    Self-sufficient: the raw function set is ``fn`` (any ``MFnNurbsCurve`` method\\n    also works via delegation, e.g. ``curve.cvPositions(...)`` keeps working).\\n    ``copy()`` returns a detached editable value you can send to an output with\\n    NO imports.\\n\\n    Construction (value/output): ``points`` (N,3 CV positions) required.\\n    Optional: ``degree`` (default 3), ``periodic`` (default False = open),\\n    ``kv`` (knot vector; auto if None). ``knots`` is an alias for ``kv``.\\n    \\"\\"\\"\\n\\n    def __init__(self, points=None, degree=3, periodic=False, kv=None):\\n        self._attached = False\\n        self._data = None          # retained api2 geometry DATA MObject\\n        self._fn = None            # cached MFnNurbsCurve (attached mode)\\n        self._tags = None          # cached component_tags dict\\n        self._points = None if points is None else np.asarray(points, dtype=np.float64)\\n        self._degree = int(degree) if degree is not None else 3\\n        self._periodic = bool(periodic)\\n        self._knots = None if kv is None else np.asarray(kv, dtype=np.float64)\\n        self._form = None          # value mode derives form from periodic\\n\\n    @classmethod\\n    def _attach(cls, data_mobject, source_plug=None):\\n        c = cls.__new__(cls)\\n        c._attached = True\\n        c._data = data_mobject\\n        c._fn = None\\n        c._tags = None\\n        c._points = None\\n        c._degree = None\\n        c._periodic = None\\n        c._knots = None\\n        c._form = None\\n        c._src_plug = source_plug\\n        c._name = None\\n        return c\\n\\n    @property\\n    def name(self):\\n        \\"\\"\\"Name of the shape feeding this curve, or None for a value curve.\\n        Lazy + cached -- see :func:`_source_node_name`.\\"\\"\\"\\n        nm = self.__dict__.get(\\"_name\\")\\n        if nm is None:\\n            nm = _source_node_name(self.__dict__.get(\\"_src_plug\\"))\\n            self.__dict__[\\"_name\\"] = nm\\n        return nm\\n\\n    # ----- raw function set + delegation -----\\n    @property\\n    def fn(self):\\n        \\"\\"\\"The live ``MFnNurbsCurve`` (attached mode), or None if detached.\\"\\"\\"\\n        f = self.__dict__.get(\\"_fn\\")\\n        if f is None:\\n            d = self.__dict__.get(\\"_data\\")\\n            if d is not None and not d.isNull():\\n                f = om.MFnNurbsCurve(d)\\n                self.__dict__[\\"_fn\\"] = f\\n        return f\\n\\n    def __getattr__(self, name):\\n        if name.startswith(\\"_\\"):\\n            raise AttributeError(name)\\n        f = self.fn\\n        if f is not None:\\n            return getattr(f, name)\\n        raise AttributeError(\\n            \\"%r: this NurbsCurve is detached (arrays only, no function set)\\" % name)\\n\\n    def _cow_detach(self):\\n        if not self.__dict__.get(\\"_attached\\"):\\n            return\\n        _ = self.points; _ = self.degree; _ = self.form; _ = self.knots\\n        try:\\n            _ = self.component_tags\\n        except Exception:\\n            pass\\n        self._attached = False\\n        self._data = None\\n        self._fn = None\\n\\n    # ----- lazy numpy read surface -----\\n    @property\\n    def points(self):\\n        v = self.__dict__.get(\\"_points\\")\\n        if v is None and self.__dict__.get(\\"_attached\\"):\\n            f = self.fn\\n            if f is not None:\\n                v = np.asarray(\\n                    f.cvPositions(om.MSpace.kObject))[:, :3].astype(np.float64)\\n                self._points = v\\n        return v\\n\\n    @points.setter\\n    def points(self, val):\\n        self._cow_detach()\\n        self._points = None if val is None else np.asarray(val, dtype=np.float64)\\n\\n    # ``cvs`` reads the same CV positions (matches the generator scratch name).\\n    @property\\n    def cvs(self):\\n        return self.points\\n\\n    @cvs.setter\\n    def cvs(self, val):\\n        self.points = val\\n\\n    @property\\n    def degree(self):\\n        v = self.__dict__.get(\\"_degree\\")\\n        if v is None and self.__dict__.get(\\"_attached\\"):\\n            f = self.fn\\n            if f is not None:\\n                v = int(f.degree)\\n                self._degree = v\\n        return v\\n\\n    @degree.setter\\n    def degree(self, val):\\n        self._cow_detach()\\n        self._degree = None if val is None else int(val)\\n\\n    @property\\n    def form(self):\\n        v = self.__dict__.get(\\"_form\\")\\n        if v is None and self.__dict__.get(\\"_attached\\"):\\n            f = self.fn\\n            if f is not None:\\n                v = int(f.form)\\n                self._form = v\\n        return v\\n\\n    @form.setter\\n    def form(self, val):\\n        self._cow_detach()\\n        self._form = val\\n\\n    @property\\n    def periodic(self):\\n        # Value mode stores an explicit bool; attached mode derives it from form.\\n        p = self.__dict__.get(\\"_periodic\\")\\n        if p is not None:\\n            return p\\n        fm = self.form\\n        return bool(fm == om.MFnNurbsCurve.kPeriodic) if fm is not None else False\\n\\n    @periodic.setter\\n    def periodic(self, val):\\n        self._cow_detach()\\n        self._periodic = bool(val)\\n\\n    @property\\n    def knots(self):\\n        v = self.__dict__.get(\\"_knots\\")\\n        if v is None and self.__dict__.get(\\"_attached\\"):\\n            f = self.fn\\n            if f is not None:\\n                v = np.asarray(f.knots(), dtype=np.float64)\\n                self._knots = v\\n        return v\\n\\n    @knots.setter\\n    def knots(self, val):\\n        self._cow_detach()\\n        self._knots = None if val is None else np.asarray(val, dtype=np.float64)\\n\\n    # ``kv`` is the name ``build_curve_data`` reads; alias it to ``knots`` so a\\n    # copy()\'d attached curve round-trips its real knot vector on output.\\n    @property\\n    def kv(self):\\n        return self.knots\\n\\n    @kv.setter\\n    def kv(self, val):\\n        self.knots = val\\n\\n    @property\\n    def component_tags(self):\\n        \\"\\"\\"``{tag_name: {\\"type\\": \\"cv\\", \\"indices\\": np}}`` (curve CV tags are\\n        single-indexed). Read live off the geometry DATA (attached mode).\\"\\"\\"\\n        t = self.__dict__.get(\\"_tags\\")\\n        if t is None:\\n            t = {}\\n            d = self.__dict__.get(\\"_data\\")\\n            if self.__dict__.get(\\"_attached\\") and d is not None and not d.isNull():\\n                try:\\n                    gd = om.MFnGeometryData(d)\\n                    for nm in gd.componentTags():\\n                        try:\\n                            comp = gd.componentTagContents(nm)\\n                            typ, idx = _decode_single_component(comp)\\n                            t[nm] = {\\"type\\": typ, \\"indices\\": idx}\\n                        except Exception:\\n                            pass\\n                except Exception:\\n                    pass\\n            self._tags = t\\n        return t\\n\\n    def region(self, tag):\\n        \\"\\"\\"CV positions of a ``cv`` tag (``(K,3)``), or its raw indices for any\\n        other tag type, or None if the tag is absent.\\"\\"\\"\\n        info = self.component_tags.get(tag)\\n        if not info:\\n            return None\\n        idx = info[\\"indices\\"]\\n        if info[\\"type\\"] == \\"cv\\":\\n            pts = self.points\\n            return pts[idx] if pts is not None else None\\n        return idx\\n\\n    def copy(self):\\n        \\"\\"\\"A DETACHED value copy (severs the .fn link). Edit its channels and\\n        assign to an output plug -- no imports required.\\"\\"\\"\\n        c = NurbsCurve()\\n        p = self.points\\n        c._points = None if p is None else np.array(p, dtype=np.float64)\\n        c._degree = self.degree\\n        c._form = self.form\\n        c._periodic = self.periodic\\n        k = self.knots\\n        c._knots = None if k is None else np.array(k, dtype=np.float64)\\n        try:\\n            c._tags = {kk: dict(vv) for kk, vv in self.component_tags.items()}\\n        except Exception:\\n            pass\\n        return c\\n\\n    # ----- serialization -----\\n    def __reduce__(self):\\n        \\"\\"\\"Pickle as a DETACHED value curve (see the Serialization section).\\"\\"\\"\\n        return (_geo_from_state, (NurbsCurve, _detached_state(self)))\\n\\n    def to_json(self):\\n        \\"\\"\\"A plain-JSON dict of every channel -- no numpy, no Maya handles.\\"\\"\\"\\n        return {\\n            \\"type\\": \\"NurbsCurve\\",\\n            \\"name\\": self.name,\\n            \\"points\\": _jlist(self.points),\\n            \\"degree\\": None if self.degree is None else int(self.degree),\\n            \\"form\\": self.form,\\n            \\"periodic\\": bool(self.periodic),\\n            \\"knots\\": _jlist(self.knots),\\n            \\"component_tags\\": _jtags(self.component_tags),\\n        }\\n\\n    @classmethod\\n    def from_json(cls, payload):\\n        \\"\\"\\"Rebuild a detached NurbsCurve from :meth:`to_json` output.\\"\\"\\"\\n        if isinstance(payload, (str, bytes)):\\n            payload = _json.loads(payload)\\n        c = cls(points=payload.get(\\"points\\"),\\n                degree=payload.get(\\"degree\\") or 3,\\n                periodic=bool(payload.get(\\"periodic\\")),\\n                kv=payload.get(\\"knots\\"))\\n        c._form = payload.get(\\"form\\")\\n        c._tags = _tags_from_json(payload.get(\\"component_tags\\"))\\n        c._name = payload.get(\\"name\\")\\n        return c\\n\\n    # ----- arithmetic -----\\n    __array_ufunc__ = None\\n\\n    def __iadd__(self, other):\\n        \\"\\"\\"Concatenate another curve\'s CVs onto this one, producing ONE longer\\n        curve through both control point sets -- not two curves in one shape.\\n\\n        Knots are dropped so the marshaller rebuilds a uniform vector for the\\n        combined CV count: the originals describe the old parameterisations and\\n        cannot be spliced. Degree and ``periodic`` must MATCH -- silently\\n        re-fitting to another degree, or appending onto a closed curve, is far\\n        more likely a mistake than an intent.\\"\\"\\"\\n        if not isinstance(other, NurbsCurve):\\n            raise TypeError(\\n                \\"NurbsCurve + %s is undefined; only another NurbsCurve can be \\"\\n                \\"concatenated\\" % type(other).__name__)\\n        if int(other.degree) != int(self.degree):\\n            raise ValueError(\\n                \\"degree mismatch: %d vs %d -- resample one curve first\\"\\n                % (int(self.degree), int(other.degree)))\\n        if bool(other.periodic) != bool(self.periodic):\\n            raise ValueError(\\n                \\"periodic mismatch: %r vs %r -- appending onto a closed curve \\"\\n                \\"is ambiguous\\" % (bool(self.periodic), bool(other.periodic)))\\n        op = other.points\\n        self._cow_detach()\\n        sp = self.__dict__.get(\\"_points\\")\\n        if op is None:\\n            return self\\n        if sp is None:\\n            self._points = np.array(op, dtype=np.float64)\\n        else:\\n            self._points = np.concatenate(\\n                [sp, np.asarray(op, dtype=np.float64)])\\n        self._knots = None\\n        return self\\n\\n    def __add__(self, other):\\n        return self.copy().__iadd__(other)\\n\\n    def __radd__(self, other):\\n        if isinstance(other, int) and other == 0:\\n            return self.copy()\\n        return self.__add__(other)\\n\\n    def to_mobject(self):\\n        # Attached + unedited: zero-copy, tag-preserving pass-through.\\n        if self.__dict__.get(\\"_attached\\"):\\n            d = self.__dict__.get(\\"_data\\")\\n            if d is not None and not d.isNull():\\n                return d\\n        return build_curve_data(self)\\n\\n    def __repr__(self):\\n        nm = self.name\\n        if nm:\\n            return \'NurbsCurve(\\"%s\\")\' % nm\\n        mode = \\"attached\\" if self.__dict__.get(\\"_attached\\") else \\"value\\"\\n        p = self.__dict__.get(\\"_points\\")\\n        n = (\\"lazy\\" if self.__dict__.get(\\"_attached\\") else 0) if p is None else len(p)\\n        return \\"<NurbsCurve %s cvs=%s>\\" % (mode, n)"}, {"module": "mpynode._api2.geometry", "name": "_decode_single_component", "source": "def _decode_single_component(comp):\\n    \\"\\"\\"Decode a single-indexed component MObject into ``(type_str, indices)``.\\n    ``indices`` is a flat ``(K,)`` int64 array.\\"\\"\\"\\n    if comp is None or comp.isNull():\\n        return \\"unknown\\", np.empty(0, dtype=np.int64)\\n    typ = _COMP_TYPE.get(comp.apiType(), \\"unknown\\")\\n    try:\\n        sic = om.MFnSingleIndexedComponent(comp)\\n        idx = np.asarray(sic.getElements(), dtype=np.int64)\\n    except Exception:\\n        idx = np.empty(0, dtype=np.int64)\\n    return typ, idx"}, {"module": "mpynode._api2.geometry", "name": "_detached_state", "source": "def _detached_state(obj):\\n    \\"\\"\\"The picklable ``__dict__`` of ``obj`` -- its channels, materialized off\\n    the live handle if attached, with the Maya handles dropped.\\"\\"\\"\\n    state = obj.copy().__dict__.copy()\\n    state.pop(\\"_data\\", None)\\n    state.pop(\\"_fn\\", None)\\n    state[\\"_attached\\"] = False\\n    state[\\"_name\\"] = obj.name          # keep the source-shape label for display\\n    return state"}, {"module": "mpynode._api2.geometry", "name": "_geo_from_state", "source": "def _geo_from_state(cls, state):\\n    \\"\\"\\"Unpickle hook: rebuild a DETACHED geometry object from its channels.\\n\\n    Module-level (pickle must import it by name) and shared by all three\\n    geometry types -- the state dict is just the detached ``__dict__``.\\"\\"\\"\\n    obj = cls.__new__(cls)\\n    obj.__dict__.update(state)\\n    return obj"}, {"module": "mpynode._api2.geometry", "name": "_jlist", "source": "def _jlist(arr):\\n    \\"\\"\\"A numpy array as nested JSON lists (or None).\\"\\"\\"\\n    return None if arr is None else np.asarray(arr).tolist()"}, {"module": "mpynode._api2.geometry", "name": "_jtags", "source": "def _jtags(tags):\\n    return {k: {\\"type\\": v.get(\\"type\\"), \\"indices\\": _jlist(v.get(\\"indices\\"))}\\n            for k, v in (tags or {}).items()}"}, {"module": "mpynode._api2.geometry", "name": "_source_node_name", "source": "def _source_node_name(plug):\\n    \\"\\"\\"Name of the node FEEDING ``plug``, or None.\\n\\n    DISPLAY ONLY -- this is what lets a geometry object print as\\n    ``Mesh(\\"pCubeShape1\\")`` instead of an anonymous blob. An attached object\\n    holds datablock DATA, which carries no identity of its own, so the identity\\n    has to come from the plug it was decoded off.\\n\\n    Resolved LAZILY and cached by the caller: it must never cost anything on the\\n    compute hot path, only when something actually displays the object. An\\n    unconnected plug has no meaningful source -- return None and let the caller\\n    fall back to a structural summary rather than naming the consuming node\\n    (``mPyMesh1`` is not the name of the mesh).\\n\\n    Not every geometry read can supply a plug: ``_read_handle_value`` is\\n    contracted plug-free for the worker-thread compute path (Hypershade swatch /\\n    Arnold), where plug access is unsafe. Objects decoded there carry\\n    ``source_plug=None`` and simply repr with their structural summary -- a\\n    display label is never worth weakening that contract.\\n    \\"\\"\\"\\n    if plug is None:\\n        return None\\n    try:\\n        src = plug.source()\\n        if src.isNull:\\n            return None\\n        return om.MFnDependencyNode(src.node()).name()\\n    except Exception:\\n        return None"}, {"module": "mpynode._api2.geometry", "name": "_tags_from_json", "source": "def _tags_from_json(payload):\\n    return {k: {\\"type\\": v.get(\\"type\\"),\\n                \\"indices\\": np.asarray(v.get(\\"indices\\") or [], dtype=np.int64)}\\n            for k, v in (payload or {}).items()}"}, {"module": "mpynode._api2.geometry", "name": "build_curve_data", "source": "def build_curve_data(obj):\\n    \\"\\"\\"Marshal a curve-like object into an ``MFnNurbsCurveData`` MObject.\\n\\n    Required attr: ``points`` (CV positions, ``(N, 3)``). Optional: ``degree``\\n    (default 3), ``periodic`` (default False), ``kv`` (knot vector; auto if\\n    None or wrong length). An optional legacy ``form`` attribute\\n    (``\\"open\\"``/``\\"closed\\"``/``\\"periodic\\"``) overrides ``periodic`` -- the\\n    ``build_default_output`` shim uses it to keep the ``closed`` form\\n    reachable. Returns an empty data MObject on failure.\\n    \\"\\"\\"\\n    data_obj = om.MFnNurbsCurveData().create()\\n\\n    cvs = _as_points(getattr(obj, \\"points\\", None), _CURVE_TAG)\\n    if cvs is None or cvs.shape[0] == 0:\\n        return data_obj\\n\\n    degree = getattr(obj, \\"degree\\", 3)\\n    degree = int(degree) if degree is not None else 3\\n    if degree not in _VALID_DEGREES:\\n        _log(f\\"[{_CURVE_TAG}] invalid degree {degree}; defaulting to 3\\")\\n        degree = 3\\n\\n    form_kind, periodic = _resolve_curve_form(obj)\\n    num_cvs = int(cvs.shape[0])\\n    if num_cvs < degree + 1:\\n        _log(f\\"[{_CURVE_TAG}] need at least degree+1 CVs ({degree + 1}); \\"\\n             f\\"got {num_cvs}; empty curve\\")\\n        return data_obj\\n\\n    kv = getattr(obj, \\"kv\\", None)\\n    if kv is None:\\n        knot_list = _curve_uniform_knots(num_cvs, degree, periodic)\\n    else:\\n        try:\\n            knot_list = [float(k) for k in\\n                         np.asarray(kv, dtype=np.float64).flatten()]\\n        except Exception:\\n            knot_list = _curve_uniform_knots(num_cvs, degree, periodic)\\n\\n    expected = _expected_knots(num_cvs, degree)\\n    if len(knot_list) != expected:\\n        if kv is not None:\\n            _log(f\\"[{_CURVE_TAG}] knot count {len(knot_list)} != expected \\"\\n                 f\\"{expected}; rebuilding uniform\\")\\n        knot_list = _curve_uniform_knots(num_cvs, degree, periodic)\\n\\n    try:\\n        pts_array = om.MPointArray([om.MPoint(float(p[0]), float(p[1]),\\n                                              float(p[2])) for p in cvs])\\n        knot_array = om.MDoubleArray([float(k) for k in knot_list])\\n        om.MFnNurbsCurve().create(pts_array, knot_array, degree, form_kind,\\n                                  False, False, data_obj)\\n    except Exception as exc:\\n        _log(f\\"[{_CURVE_TAG}] MFnNurbsCurve.create failed: {exc}\\")\\n        import traceback\\n        traceback.print_exc(file=sys.stderr)\\n        return om.MFnNurbsCurveData().create()\\n    return data_obj"}, {"module": "mpynode._api2.geometry", "name": "_as_points", "source": "def _as_points(arr, tag):\\n    \\"\\"\\"Coerce ``arr`` to an ``(N, 3)`` float64 array, or None.\\"\\"\\"\\n    if arr is None:\\n        return None\\n    try:\\n        out = np.asarray(arr, dtype=np.float64)\\n    except Exception:\\n        _log(f\\"[{tag}] points not float-coercible\\")\\n        return None\\n    if out.ndim != 2 or out.shape[1] != 3:\\n        _log(f\\"[{tag}] points must be (N, 3); got shape {out.shape}\\")\\n        return None\\n    return out"}, {"module": "mpynode._api2.geometry", "name": "_curve_uniform_knots", "source": "def _curve_uniform_knots(num_cvs, degree, periodic):\\n    \\"\\"\\"Uniform knot vector, length ``num_cvs + degree - 1`` for both forms.\\n    Open: clamped (multiplicity ``degree`` at the ends). Periodic: continuous\\n    integers ``[-degree+1 .. num_cvs-1]`` (matches Maya\'s periodic convention;\\n    the caller must supply CVs that already wrap).\\"\\"\\"\\n    n_knots = _expected_knots(num_cvs, degree)\\n    if n_knots <= 0:\\n        return []\\n    if periodic:\\n        return [float(i - degree + 1) for i in range(n_knots)]\\n    inner = max(n_knots - 2 * degree, 0)\\n    knots = [0.0] * degree\\n    knots.extend(float(i + 1) for i in range(inner))\\n    knots.extend([float(inner + 1)] * degree)\\n    return knots[:n_knots]"}, {"module": "mpynode._api2.geometry", "name": "_expected_knots", "source": "def _expected_knots(num_cvs, degree):\\n    \\"\\"\\"Knot count Maya\'s ``MFn*::create`` expects: ``num_cvs + degree - 1``\\n    for BOTH open and periodic forms (verified against a stock periodic\\n    circle: 11 CVs, degree 3 -> 13 knots = 11 + 3 - 1).\\"\\"\\"\\n    return num_cvs + degree - 1"}, {"module": "mpynode._api2.geometry", "name": "_log", "source": "def _log(msg: str) -> None:\\n    sys.stderr.write(msg if msg.endswith(\\"\\\\n\\") else msg + \\"\\\\n\\")"}, {"module": "mpynode._api2.geometry", "name": "_resolve_curve_form", "source": "def _resolve_curve_form(obj):\\n    \\"\\"\\"Return ``(form_kind, periodic_bool)``.\\n\\n    Honors an optional legacy ``form`` attribute (a string\\n    ``\\"open\\"``/``\\"closed\\"``/``\\"periodic\\"`` or an int ``MFnNurbsCurve`` form\\n    constant) which the ``build_default_output`` shim passes through so the\\n    ``closed`` form the periodic-only :class:`NurbsCurve` can\'t express is not\\n    lost. If ``form`` is absent (the dataclass case) it falls back to the\\n    ``periodic`` bool. ``periodic_bool`` drives uniform knot generation\\n    (clamped vs continuous), so ``closed`` -> ``False`` -> clamped knots,\\n    matching the legacy marshaller.\\"\\"\\"\\n    form = getattr(obj, \\"form\\", None)\\n    if form is not None:\\n        if isinstance(form, str):\\n            kind = _CURVE_FORM_BY_NAME.get(form.lower(), om.MFnNurbsCurve.kOpen)\\n        elif isinstance(form, int) and not isinstance(form, bool):\\n            kind = int(form)\\n        else:\\n            kind = om.MFnNurbsCurve.kOpen\\n        return kind, (kind == om.MFnNurbsCurve.kPeriodic)\\n    periodic = bool(getattr(obj, \\"periodic\\", False))\\n    return (om.MFnNurbsCurve.kPeriodic if periodic\\n            else om.MFnNurbsCurve.kOpen), periodic"}], "methods": "@maya_test(label=\\"Helix builds a 120-CV degree-3 curve of the right radius\\", digits=4)\\ndef test_helix(self):\\n    \\"\\"\\"Validate the node\'s INTENT (same test drives the interpreted node AND its\\n    C++ compile -> parity): the generator builds a real 120-CV degree-3\\n    nurbsCurve whose X-extent tracks 2*radius. Drives ONLY public plugs + cmds,\\n    so it is valid against the compiled node too.\\"\\"\\"\\n    from maya import cmds as mc\\n    import maya.api.OpenMaya as om2\\n    from mpynode._common.methods.test_helpers import assert_true\\n\\n    name = self.get_name()\\n\\n    def _set(plug, *vals):\\n        for s in (mc.listConnections(plug, s=True, d=False, plugs=True) or []):\\n            mc.disconnectAttr(s, plug)\\n        mc.setAttr(plug, *vals)\\n\\n    # Build a real nurbsCurve shape driven by outCurve (idempotent: reuse the\\n    # one this node already drives, if any).\\n    dst = mc.listConnections(name + \\".outCurve\\", s=False, d=True, plugs=True) or []\\n    shp = None\\n    for d in dst:\\n        node = d.split(\\".\\")[0]\\n        if mc.nodeType(node) == \\"nurbsCurve\\":\\n            shp = node\\n            break\\n    if shp is None:\\n        xf = mc.createNode(\\"transform\\", name=\\"helixTest#\\")\\n        shp = mc.createNode(\\"nurbsCurve\\", name=xf + \\"Shape\\", parent=xf)\\n        mc.connectAttr(name + \\".outCurve\\", shp + \\".create\\", force=True)\\n\\n    _set(name + \\".radius\\", 2.5)\\n    _set(name + \\".turns\\", 3.0)\\n    _set(name + \\".height\\", 6.0)\\n    mc.currentTime(1)\\n    mc.dgeval(shp + \\".create\\")\\n\\n    spans = mc.getAttr(shp + \\".spans\\")\\n    deg = mc.getAttr(shp + \\".degree\\")\\n    cv_count = spans + deg          # open curve: #CVs = spans + degree\\n    assert_true(cv_count == 120, \\"expected 120 CVs, got %r\\" % cv_count)\\n    assert_true(deg == 3, \\"expected degree 3, got %r\\" % deg)\\n\\n    sel = om2.MSelectionList(); sel.add(shp)\\n    fn = om2.MFnNurbsCurve(sel.getDagPath(0))\\n    xs = [p.x for p in fn.cvPositions(om2.MSpace.kObject)]\\n    x_extent = max(xs) - min(xs)\\n    assert_true(abs(x_extent - 5.0) < 0.5,\\n                \\"X-extent %.3f should track 2*radius=5.0\\" % x_extent)\\n\\n\\n@maya_demo(label=\\"Animated Helix Curve\\")\\ndef demo(self):\\n    \\"\\"\\"Build a nurbsCurve shape driven by this generator, tune a wide coil, set a\\n    one-loop playback range and press-play-ready timeline. The coil slowly spins\\n    because `t` is wired to the timeline.\\"\\"\\"\\n    from maya import cmds as mc\\n    name = self.get_name()\\n\\n    xf = mc.createNode(\\"transform\\", name=\\"helixCurve#\\")\\n    shp = mc.createNode(\\"nurbsCurve\\", name=xf + \\"Shape\\", parent=xf)\\n    mc.connectAttr(name + \\".outCurve\\", shp + \\".create\\", force=True)\\n    # `t` auto-connects to time1 on create; re-assert if the apply path dropped it.\\n    if not (mc.listConnections(name + \\".t\\", s=True, d=False) or []):\\n        try:\\n            mc.connectAttr(\\"time1.outTime\\", name + \\".t\\", force=True)\\n        except Exception:\\n            pass\\n\\n    mc.setAttr(name + \\".radius\\", 2.5)\\n    mc.setAttr(name + \\".turns\\", 4.0)\\n    mc.setAttr(name + \\".height\\", 6.0)\\n    mc.playbackOptions(min=1, max=120)\\n    mc.currentTime(1)\\n    mc.select(xf, replace=True)\\n    try:\\n        for _panel in mc.getPanel(type=\\"modelPanel\\") or []:\\n            _cam = mc.modelEditor(_panel, query=True, camera=True)\\n            if _cam:\\n                mc.viewFit(_cam, allObjects=True)\\n    except Exception:\\n        pass\\n    return name\\n\\n\\n\\"\\"\\"Setup source for mPyNurbsCurve nodes (self-first instance method).\\"\\"\\"\\n\\n# Also this node\'s CREATE command, the way cmds.blendShape both makes the node\\n# and wires it. Un-named because this file is shared by every node of the type\\n# -- see maya_command.resolve_create_command_names.\\n@maya_command(creates=True)\\ndef setup(self, *args, **kwargs):\\n    from maya import cmds as mc\\n    name = self.get_name()\\n    # build() owns ``self`` -- never delete it on failure. Only roll back the\\n    # render transform/shape this body creates so a partial failure leaves no\\n    # orphan; re-raise so build()/the command records built-but-unwired.\\n    created = []\\n    conn = None  # break any wired connection before delete so the rollback\\n                 # doesn\'t cascade-delete the upstream ``self``.\\n    try:\\n        xform = mc.createNode(\\"transform\\", name=name + \\"Render\\"); created.append(xform)\\n        shape = mc.createNode(\\"nurbsCurve\\", name=name + \\"RenderShape\\", parent=xform)\\n        src, dst = name + \\".outCurve\\", shape + \\".create\\"\\n        mc.connectAttr(src, dst, force=True); conn = (src, dst)\\n        return name\\n    except Exception:\\n        if conn:\\n            try:\\n                mc.disconnectAttr(conn[0], conn[1])\\n            except Exception:\\n                pass\\n        if created:\\n            mc.delete([n for n in created if mc.objExists(n)])\\n        raise\\n", "commands": [{"name": "helixCurve", "name_explicit": false, "func_name": "setup", "undoable": true, "creates": true, "is_factory": false, "is_static": false, "params": [], "body_src": "@maya_command(creates=True)\\ndef setup(self, *args, **kwargs):\\n    from maya import cmds as mc\\n    name = self.get_name()\\n    # build() owns ``self`` -- never delete it on failure. Only roll back the\\n    # render transform/shape this body creates so a partial failure leaves no\\n    # orphan; re-raise so build()/the command records built-but-unwired.\\n    created = []\\n    conn = None  # break any wired connection before delete so the rollback\\n                 # doesn\'t cascade-delete the upstream ``self``.\\n    try:\\n        xform = mc.createNode(\\"transform\\", name=name + \\"Render\\"); created.append(xform)\\n        shape = mc.createNode(\\"nurbsCurve\\", name=name + \\"RenderShape\\", parent=xform)\\n        src, dst = name + \\".outCurve\\", shape + \\".create\\"\\n        mc.connectAttr(src, dst, force=True); conn = (src, dst)\\n        return name\\n    except Exception:\\n        if conn:\\n            try:\\n                mc.disconnectAttr(conn[0], conn[1])\\n            except Exception:\\n                pass\\n        if created:\\n            mc.delete([n for n in created if mc.objExists(n)])\\n        raise", "lineno": 92}], "portability": {"portable": true, "blockers": [], "warnings": ["uses numpy -- vectorized math is reverse-engineered to C++ loops (verify numerically; np.random maps to C++ <random>; file I/O lowers only where the dtype is explicit -- np.fromfile/np.save/.tofile and ndio.read/ndio.write -- while np.load/np.loadtxt are blockers)"], "unported": [], "reads_image_file": false, "reads_embedded_image": false, "uses_mesh_intersector": false}}')


def run():
    from mpynode.native.toolchain import verify as _cc
    if not cmds.pluginInfo(os.path.basename(BUNDLE), q=True, loaded=True):
        cmds.loadPlugin(BUNDLE)
    row = _cc._verify_one(cmds, BUNDLE, SPEC)
    print("GEO VERIFY", row)
    if not row.get("ran"):
        print("VERIFY SKIP (" + str(row.get("reason")) + ")")
        return True
    if row.get("pass"):
        print("VERIFY PASS maxerr", row.get("maxerr"))
        return True
    print("VERIFY FAIL", row.get("reason"), row.get("maxerr"))
    return False


if __name__ == "__main__":
    run()
